[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "mortgage_comparison_surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "mortgage_comparison_surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "header",
            "assumptions",
            "optionsTabs",
            "divider1",
            "tableTitle",
            "tableCard",
            "divider2",
            "actionsRow",
            "sources"
          ],
          "spacing": 16
        },
        {
          "id": "header",
          "component": "Text",
          "text": "Mortgage Options Comparison",
          "variant": "h2"
        },
        {
          "id": "assumptions",
          "component": "Text",
          "text": "Assumptions: Property taxes, insurance, and PMI excluded. 20% down ($100k) on a $400k loan.",
          "variant": "caption"
        },
        {
          "id": "optionsTabs",
          "component": "Tabs",
          "tabs": [
            {
              "title": "Option A: 30yr Fixed",
              "child": "optionACol"
            },
            {
              "title": "Option B: 15yr Fixed",
              "child": "optionBCol"
            },
            {
              "title": "Option C: 5/1 ARM",
              "child": "optionCCol"
            }
          ]
        },
        {
          "id": "optionACol",
          "component": "Column",
          "children": ["txtA"]
        },
        {
          "id": "txtA",
          "component": "Text",
          "text": "**Rate:** 6.5%\n**Monthly P&I:** $2,528.27\n**Total Interest:** $510,177.20\n**Total Loan Cost:** $910,177.20",
          "variant": "body"
        },
        {
          "id": "optionBCol",
          "component": "Column",
          "children": ["txtB"]
        },
        {
          "id": "txtB",
          "component": "Text",
          "text": "**Rate:** 5.75%\n**Monthly P&I:** $3,320.35\n**Total Interest:** $197,663.00\n**Total Loan Cost:** $597,663.00",
          "variant": "body"
        },
        {
          "id": "optionCCol",
          "component": "Column",
          "children": ["txtC"]
        },
        {
          "id": "txtC",
          "component": "Text",
          "text": "**Initial Rate:** 5.5% (Years 1-5)\n**Adjusted Rate:** 7.5% (Years 6-30)\n**Monthly P&I (1-5):** $2,271.16\n**Monthly P&I (6-30):** $2,732.32\n**Total Interest:** $555,965.60\n**Total Loan Cost:** $955,965.60",
          "variant": "body"
        },
        {
          "id": "divider1",
          "component": "Divider"
        },
        {
          "id": "tableTitle",
          "component": "Text",
          "text": "Comparison Table",
          "variant": "h4"
        },
        {
          "id": "tableCard",
          "component": "Card",
          "child": "tableCol"
        },
        {
          "id": "tableCol",
          "component": "Column",
          "children": ["rowH", "rowA", "rowB", "rowC"]
        },
        {
          "id": "rowH",
          "component": "Row",
          "justify": "spaceBetween",
          "children": ["h1", "h2", "h3", "h4"]
        },
        {
          "id": "h1",
          "component": "Text",
          "text": "**Option**",
          "variant": "caption"
        },
        {
          "id": "h2",
          "component": "Text",
          "text": "**Term**",
          "variant": "caption"
        },
        {
          "id": "h3",
          "component": "Text",
          "text": "**Rate**",
          "variant": "caption"
        },
        {
          "id": "h4",
          "component": "Text",
          "text": "**Monthly**",
          "variant": "caption"
        },
        {
          "id": "rowA",
          "component": "Row",
          "justify": "spaceBetween",
          "children": ["a1", "a2", "a3", "a4"]
        },
        {
          "id": "a1",
          "component": "Text",
          "text": "Option A",
          "variant": "body"
        },
        {
          "id": "a2",
          "component": "Text",
          "text": "30yr",
          "variant": "body"
        },
        {
          "id": "a3",
          "component": "Text",
          "text": "6.50%",
          "variant": "body"
        },
        {
          "id": "a4",
          "component": "Text",
          "text": "$2,528",
          "variant": "body"
        },
        {
          "id": "rowB",
          "component": "Row",
          "justify": "spaceBetween",
          "children": ["b1", "b2", "b3", "b4"]
        },
        {
          "id": "b1",
          "component": "Text",
          "text": "Option B",
          "variant": "body"
        },
        {
          "id": "b2",
          "component": "Text",
          "text": "15yr",
          "variant": "body"
        },
        {
          "id": "b3",
          "component": "Text",
          "text": "5.75%",
          "variant": "body"
        },
        {
          "id": "b4",
          "component": "Text",
          "text": "$3,320",
          "variant": "body"
        },
        {
          "id": "rowC",
          "component": "Row",
          "justify": "spaceBetween",
          "children": ["c1", "c2", "c3", "c4"]
        },
        {
          "id": "c1",
          "component": "Text",
          "text": "Option C",
          "variant": "body"
        },
        {
          "id": "c2",
          "component": "Text",
          "text": "5/1 ARM",
          "variant": "body"
        },
        {
          "id": "c3",
          "component": "Text",
          "text": "5.5/7.5%",
          "variant": "body"
        },
        {
          "id": "c4",
          "component": "Text",
          "text": "$2,271+",
          "variant": "body"
        },
        {
          "id": "divider2",
          "component": "Divider"
        },
        {
          "id": "actionsRow",
          "component": "Row",
          "justify": "start",
          "children": ["btnTexas", "btnAustin"]
        },
        {
          "id": "btnTexas",
          "component": "Button",
          "child": "txtBtnTexas",
          "variant": "primary",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.bankrate.com/mortgage/rates/texas/"
              }
            }
          }
        },
        {
          "id": "txtBtnTexas",
          "component": "Text",
          "text": "Compare Texas Rates"
        },
        {
          "id": "btnAustin",
          "component": "Button",
          "child": "txtBtnAustin",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.traviscad.org/"
              }
            }
          }
        },
        {
          "id": "txtBtnAustin",
          "component": "Text",
          "text": "Austin Property Tax Info"
        },
        {
          "id": "sources",
          "component": "Text",
          "text": "Sources: consumerfinance.gov, freddiemac.com",
          "variant": "caption"
        }
      ]
    }
  }
]

