[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "techgear_analysis_2023",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "techgear_analysis_2023",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "header_text",
            "summary_card",
            "table_title",
            "table_card",
            "rec_card"
          ],
          "spacing": 16
        },
        {
          "id": "header_text",
          "component": "Text",
          "text": "Analysis for TechGear Corp (2023)",
          "variant": "h2"
        },
        {
          "id": "summary_card",
          "component": "Card",
          "child": "summary_col"
        },
        {
          "id": "summary_col",
          "component": "Column",
          "children": [
            "total_rev_text",
            "avg_rev_text"
          ]
        },
        {
          "id": "total_rev_text",
          "component": "Text",
          "text": "**Total Annual Revenue:** $1,960,000",
          "variant": "body"
        },
        {
          "id": "avg_rev_text",
          "component": "Text",
          "text": "**Average Quarterly Revenue:** $490,000",
          "variant": "body"
        },
        {
          "id": "table_title",
          "component": "Text",
          "text": "Quarterly Performance Data",
          "variant": "h4"
        },
        {
          "id": "table_card",
          "component": "Card",
          "child": "table_col"
        },
        {
          "id": "table_col",
          "component": "Column",
          "children": [
            "header_row",
            "table_divider",
            "q1_row",
            "q2_row",
            "q3_row",
            "q4_row"
          ]
        },
        {
          "id": "header_row",
          "component": "Row",
          "children": [
            "h_q",
            "h_r",
            "h_g"
          ],
          "justify": "spaceBetween"
        },
        {
          "id": "h_q",
          "component": "Text",
          "text": "Quarter",
          "variant": "caption",
          "weight": 1
        },
        {
          "id": "h_r",
          "component": "Text",
          "text": "Revenue",
          "variant": "caption",
          "weight": 1
        },
        {
          "id": "h_g",
          "component": "Text",
          "text": "Growth %",
          "variant": "caption",
          "weight": 1
        },
        {
          "id": "table_divider",
          "component": "Divider"
        },
        {
          "id": "q1_row",
          "component": "Row",
          "children": [
            "q1_q",
            "q1_r",
            "q1_g"
          ]
        },
        {
          "id": "q1_q",
          "component": "Text",
          "text": "Q1",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q1_r",
          "component": "Text",
          "text": "$450,000",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q1_g",
          "component": "Text",
          "text": "N/A",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q2_row",
          "component": "Row",
          "children": [
            "q2_q",
            "q2_r",
            "q2_g"
          ]
        },
        {
          "id": "q2_q",
          "component": "Text",
          "text": "Q2",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q2_r",
          "component": "Text",
          "text": "$380,000",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q2_g",
          "component": "Text",
          "text": "-15.56%",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q3_row",
          "component": "Row",
          "children": [
            "q3_q",
            "q3_r",
            "q3_g"
          ]
        },
        {
          "id": "q3_q",
          "component": "Text",
          "text": "Q3",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q3_r",
          "component": "Text",
          "text": "$510,000",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q3_g",
          "component": "Text",
          "text": "+34.21%",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q4_row",
          "component": "Row",
          "children": [
            "q4_q",
            "q4_r",
            "q4_g"
          ]
        },
        {
          "id": "q4_q",
          "component": "Text",
          "text": "Q4",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q4_r",
          "component": "Text",
          "text": "$620,000",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "q4_g",
          "component": "Text",
          "text": "+21.57%",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "rec_card",
          "component": "Card",
          "child": "rec_col"
        },
        {
          "id": "rec_col",
          "component": "Column",
          "children": [
            "rec_title",
            "rec_body"
          ]
        },
        {
          "id": "rec_title",
          "component": "Text",
          "text": "Visualization Recommendation",
          "variant": "h5"
        },
        {
          "id": "rec_body",
          "component": "Text",
          "text": "A Combination Chart (Line and Bar) is recommended. Use Bars to represent the absolute revenue for each quarter to show volume, and an overlaying Line to represent the percentage growth rate. This highlights the sharp recovery in Q3 and the peak volume in Q4.",
          "variant": "body"
        }
      ]
    }
  }
]

