  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "cyberpunk_essentials_surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "cyberpunk_essentials_surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "txt_summary_hdr",
            "txt_summary_body",
            "txt_assumptions",
            "div_1",
            "txt_list_hdr",
            "card_1",
            "card_2",
            "card_3",
            "card_4",
            "card_5",
            "btn_collection",
            "txt_sources"
          ],
          "spacing": 12
        },
        {
          "id": "txt_summary_hdr",
          "component": "Text",
          "text": "SUMMARY",
          "variant": "h2"
        },
        {
          "id": "txt_summary_body",
          "component": "Text",
          "text": "Cyberpunk as a genre is defined by the juxtaposition of advanced technological achievement and social decay. This list highlights foundational films that established the aesthetic of neon-lit rain, corporate dominance, and underground rebellion.",
          "variant": "body"
        },
        {
          "id": "txt_assumptions",
          "component": "Text",
          "text": "Assumptions: Classic status is based on cultural impact and genre-defining tropes.",
          "variant": "caption"
        },
        {
          "id": "div_1",
          "component": "Divider",
          "axis": "horizontal"
        },
        {
          "id": "txt_list_hdr",
          "component": "Text",
          "text": "CYBERPUNK ESSENTIALS (1982-1999)",
          "variant": "h3"
        },
        {
          "id": "card_1",
          "component": "Card",
          "child": "col_m1"
        },
        {
          "id": "col_m1",
          "component": "Column",
          "children": [
            "txt_m1_title",
            "txt_m1_desc"
          ]
        },
        {
          "id": "txt_m1_title",
          "component": "Text",
          "text": "**Blade Runner (1982)**",
          "variant": "h5"
        },
        {
          "id": "txt_m1_desc",
          "component": "Text",
          "text": "Ridley Scott | **High Tech:** Bio-engineered Replicants / **Low Life:** Gritty, overpopulated Los Angeles.",
          "variant": "body"
        },
        {
          "id": "card_2",
          "component": "Card",
          "child": "col_m2"
        },
        {
          "id": "col_m2",
          "component": "Column",
          "children": [
            "txt_m2_title",
            "txt_m2_desc"
          ]
        },
        {
          "id": "txt_m2_title",
          "component": "Text",
          "text": "**Akira (1988)**",
          "variant": "h5"
        },
        {
          "id": "txt_m2_desc",
          "component": "Text",
          "text": "Katsuhiro Otomo | **High Tech:** Secret government psychic experiments / **Low Life:** Biker gangs in a post-apocalyptic Neo-Tokyo.",
          "variant": "body"
        },
        {
