          "component": "Text",
          "text": "Instant Vortex Plus",
          "weight": 2
        },
        {
          "id": "r3_c",
          "component": "Text",
          "text": "6-Qt",
          "weight": 1
        },
        {
          "id": "r3_w",
          "component": "Text",
          "text": "1700W",
          "weight": 1
        },
        {
          "id": "r3_p",
          "component": "Text",
          "text": "$159",
          "weight": 1
        },
