          "id": "rankings_list",
          "component": "List",
          "children": [
            "rank_1",
            "rank_2",
            "rank_3"
          ],
          "direction": "vertical"
        },
        {
          "id": "rank_1",
          "component": "Text",
          "text": "1. **Cosori Pro II**: Best Value ($20.51 per quart)"
        },
        {
          "id": "rank_2",
          "component": "Text",
          "text": "2. **Instant Vortex Plus**: Mid-range Value ($26.50 per quart)"
        },
        {
          "id": "rank_3",
          "component": "Text",
          "text": "3. **Ninja AF101**: Lowest Value ($32.25 per quart)"
        },
        {
          "id": "insights_section_title",
          "component": "Text",
          "text": "Performance Insight",
          "variant": "h2"
        },
        {
          "id": "insights_list",
          "component": "List",
          "children": [
            "insight_1",
            "insight_2"
          ],
          "direction": "vertical"
        },
        {
          "id": "insight_1",
          "component": "Text",
          "text": "• **Highest Wattage**: Both the Cosori Pro II and the Instant Vortex Plus offer 1700W, which generally leads to faster preheating and crispier results compared to the 1550W Ninja model."
        },
        {
          "id": "insight_2",
          "component": "Text",
          "text": "• **Largest Capacity**: The Instant Vortex Plus offers the most cooking space at 6 quarts."
        },
        {
          "id": "recommendation_section_title",
          "component": "Text",
          "text": "Recommendation",
          "variant": "h2"
        },
        {
          "id": "recommendation_list",
          "component": "List",
          "children": [
            "rec_1",
            "rec_2"
          ],
          "direction": "vertical"
        },
        {
          "id": "rec_1",
          "component": "Text",
          "text": "• **For Budget & Efficiency**: Cosori Pro II offers the best balance of high wattage and the most capacity for every dollar spent."
        },
        {
          "id": "rec_2",
          "component": "Text",
          "text": "• **For Brand Reliability**: Ninja AF101 is a compact choice for smaller kitchens despite the lower value-to-size ratio."
        },
        {
          "id": "action_button",
          "component": "Button",
          "child": "button_label",
          "variant": "primary",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://cosori.com/products/pro-ii-air-fryer-5-8-quart"
              }
            }
          }
        },
        {
          "id": "button_label",
          "component": "Text",
          "text": "View Cosori Pro II"
        }
      ]
    }
  }
]

