          "id": "h-3s",
          "component": "Text",
          "text": "**3-Season**",
          "variant": "caption",
          "weight": 1
        },
        {
          "id": "h-4s",
          "component": "Text",
          "text": "**4-Season**",
          "variant": "caption",
          "weight": 1
        },
        {
          "id": "table-divider-1",
          "component": "Divider"
        },
        {
          "id": "table-row-1",
          "component": "Row",
          "children": [
            "r1-feat",
            "r1-3s",
            "r1-4s"
          ]
        },
        {
          "id": "r1-feat",
          "component": "Text",
          "text": "Poles",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "r1-3s",
          "component": "Text",
          "text": "Thinner aluminum (8.5-9mm)",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "r1-4s",
          "component": "Text",
          "text": "Thicker (9.5mm+); rigid",
          "variant": "body",
          "weight": 1
