          "component": "Text",
          "text": "Mesh %",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "r2-3s",
          "component": "Text",
          "text": "High (50-70%)",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "r2-4s",
          "component": "Text",
          "text": "Minimal; solid fabric",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "table-row-3",
          "component": "Row",
          "children": [
            "r3-feat",
            "r3-3s",
            "r3-4s"
          ]
        },
        {
          "id": "r3-feat",
          "component": "Text",
          "text": "Snow Load",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "r3-3s",
          "component": "Text",
          "text": "Low; may collapse",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "r3-4s",
          "component": "Text",
          "text": "High; sheds snow",
          "variant": "body",
          "weight": 1
        },
        {
          "id": "recommendation-card",
          "component": "Card",
          "child": "rec-container"
        },
        {
          "id": "rec-container",
          "component": "Column",
          "children": [
            "rec-header",
            "rec-body"
          ]
        },
        {
          "id": "rec-header",
          "component": "Row",
          "children": [
            "rec-icon",
            "rec-title"
          ],
          "align": "center"
        },
        {
          "id": "rec-icon",
          "component": "Image",
          "url": "/mountain.png",
          "variant": "icon"
        },
        {
          "id": "rec-title",
          "component": "Text",
          "text": "Scottish Highlands (July)",
          "variant": "h4"
        },
        {
          "id": "rec-body",
          "component": "Text",
          "text": "**Recommendation: 3-Season Tent**\n\nJuly in the Highlands is characterized by rain and strong winds, but not heavy snow. A 3-season tent offers the necessary ventilation to combat condensation and is significantly lighter for long treks. Ensure a sturdy 'semi-geodesic' or 'tunnel' design for Highland winds.",
          "variant": "body"
        },
        {
          "id": "gear-section",
          "component": "Column",
          "children": [
            "gear-title",
            "gear-list"
          ]
        },
        {
          "id": "gear-title",
          "component": "Text",
          "text": "Essential Gear for Scotland July",
          "variant": "h4"
        },
        {
          "id": "gear-list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "gear-item-1",
            "gear-item-2",
            "gear-item-3"
          ]
        },
        {
          "id": "gear-item-1",
          "component": "Text",
          "text": "• Sturdy tent stakes (for boggy or rocky ground)",
          "variant": "body"
        },
        {
          "id": "gear-item-2",
          "component": "Text",
          "text": "• High-quality rain fly with high hydrostatic head",
          "variant": "body"
        },
        {
          "id": "gear-item-3",
          "component": "Text",
          "text": "• Bug mesh (essential for Highland midges)",
          "variant": "body"
        }
      ]
    }
  }
]

