text:
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "chair-comparison-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "chair-comparison-surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "summary_h",
            "summary_b",
            "comp_h",
            "lumbar_card",
            "armrest_card",
            "tilt_card",
            "actions_row",
            "sources_h",
            "source_1",
            "source_2"
          ],
          "justify": "start",
          "align": "stretch"
        },
        {
          "id": "summary_h",
          "component": "Text",
          "text": "Summary",
          "variant": "h2"
        },
        {
          "id": "summary_b",
          "component": "Text",
          "text": "The Herman Miller Aeron is a classic mesh task chair focused on suspended support, while the Steelcase Gesture is designed for modern tech users, supporting a wide range of postures and device-usage styles.",
          "variant": "body"
        },
        {
          "id": "comp_h",
          "component": "Text",
          "text": "Ergonomic Feature Comparison",
          "variant": "h3"
        },
        {
          "id": "lumbar_card",
          "component": "Card",
          "child": "lumbar_col"
        },
        {
          "id": "lumbar_col",
          "component": "Column",
          "children": [
            "lumbar_t",
            "lumbar_a",
            "lumbar_g"
          ]
        },
        {
          "id": "lumbar_t",
          "component": "Text",
          "text": "Lumbar Support",
          "variant": "h4"
        },
        {
          "id": "lumbar_a",
          "component": "Text",
          "text": "**Aeron (Size B):** Features the PostureFit SL system. It uses two adjustable pads that stabilize the sacrum and support the lumbar region of the spine to mimic a standing posture.",
          "variant": "body"
        },
        {
          "id": "lumbar_g",
          "component": "Text",
          "text": "**Gesture:** Features '3D LiveBack' technology. The backrest automatically contours to mimic the natural movement of the spine, providing continuous support as you change positions.",
          "variant": "body"
        },
        {
          "id": "armrest_card",
          "component": "Card",
          "child": "armrest_col"
        },
        {
          "id": "armrest_col",
          "component": "Column",
          "children": [
            "armrest_t",
            "armrest_a",
            "armrest_g"
          ]
        },
        {
          "id": "armrest_t",
          "component": "Text",
          "text": "Armrest Movement",
          "variant": "h4"
        },
        {
          "id": "armrest_a",
          "component": "Text",
          "text": "**Aeron (Size B):** 3D Armrests. They adjust for height, depth (sliding forward/backward), and pivot (turning inward/outward). They are attached to the seat back.",
          "variant": "body"
        },
        {
          "id": "armrest_g",
          "component": "Text",
          "text": "**Gesture:** 4D Armrests. Known for the best range in the industry, they adjust for height, width, depth, and 360-degree pivot. They are designed to support users holding mobile devices or tablets.",
          "variant": "body"
        },
        {
          "id": "tilt_card",
          "component": "Card",
          "child": "tilt_col"
        },
        {
          "id": "tilt_col",
          "component": "Column",
          "children": [
            "tilt_t",
            "tilt_a",
            "tilt_g"
          ]
        },
        {
          "id": "tilt_t",
          "component": "Text",
          "text": "Tilt Options",
          "variant": "h4"
        },
        {
          "id": "tilt_a",
          "component": "Text",
          "text": "**Aeron (Size B):** Standard model includes a Tilt Limiter with three settings (upright, mid-recline, full recline) and a Seat Angle adjustment (Forward Tilt) for engaged tasks.",
          "variant": "body"
        },
        {
          "id": "tilt_g",
          "component": "Text",
          "text": "**Gesture:** Features a variable back stop with four positions. It lacks the forward tilt option found on the Aeron but offers a more seamless 'synchro-tilt' that keeps feet flat on the floor while reclining.",
          "variant": "body"
        },
        {
          "id": "actions_row",
          "component": "Row",
          "children": [
            "btn_aeron",
            "btn_gesture"
          ],
          "justify": "start"
        },
        {
          "id": "btn_aeron",
          "component": "Button",
          "child": "btn_aeron_t",
          "variant": "primary",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.hermanmiller.com/products/seating/office-chairs/aeron-chairs/"
              }
            }
          }
        },
        {
          "id": "btn_aeron_t",
          "component": "Text",
          "text": "View Aeron"
        },
        {
          "id": "btn_gesture",
          "component": "Button",
          "child": "btn_gesture_t",
          "variant": "primary",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.steelcase.com/products/office-chairs/gesture/"
              }
            }
          }
        },
        {
          "id": "btn_gesture_t",
          "component": "Text",
          "text": "View Gesture"
        },
        {
          "id": "sources_h",
          "component": "Text",
          "text": "Sources:",
          "variant": "caption"
        },
        {
          "id": "source_1",
          "component": "Text",
          "text": "• Herman Miller Aeron Adjustment Guide",
          "variant": "caption"
        },
        {
          "id": "source_2",
          "component": "Text",
          "text": "• Steelcase Gesture User Guide",
          "variant": "caption"
        }
      ]
    }
  }
]

