text:
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "seattle-rose-pruning-guide",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "seattle-rose-pruning-guide",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "header-row",
            "divider-1",
            "design-col",
            "rec-card",
            "damage-col",
            "tips-card",
            "action-row"
          ],
          "align": "stretch"
        },
        {
          "id": "header-row",
          "component": "Row",
          "children": [
            "icon-gardening",
            "title-text"
          ],
          "align": "center"
        },
        {
          "id": "icon-gardening",
          "component": "Image",
          "url": "/potted-plant.png",
          "variant": "icon"
        },
        {
          "id": "title-text",
          "component": "Text",
          "text": "Pruning Shears Guide for Seattle Rose Gardens",
          "variant": "h2"
        },
        {
          "id": "divider-1",
          "component": "Divider"
        },
        {
          "id": "design-col",
          "component": "Column",
          "children": [
            "design-h",
            "bypass-desc",
            "anvil-desc"
          ]
        },
        {
          "id": "design-h",
          "component": "Text",
          "text": "Differences in Design",
          "variant": "h3"
        },
        {
          "id": "bypass-desc",
          "component": "Text",
          "text": "**Bypass Pruners**: These work like scissors, where two sharp blades pass by each other. This creates a clean, precise cut.",
          "variant": "body"
        },
        {
          "id": "anvil-desc",
          "component": "Text",
          "text": "**Anvil Pruners**: These have one sharp blade that closes down onto a flat metal or plastic plate (the anvil). This works like a knife on a chopping board.",
          "variant": "body"
        },
        {
          "id": "rec-card",
          "component": "Card",
          "child": "rec-col"
        },
        {
          "id": "rec-col",
          "component": "Column",
          "children": [
            "rec-h",
            "rec-body"
          ]
        },
        {
          "id": "rec-h",
          "component": "Text",
          "text": "Recommendation for Rose Stems",
          "variant": "h4"
        },
        {
          "id": "rec-body",
          "component": "Text",
          "text": "**Recommendation**: Bypass Pruning Shears\n\n**Reason**: Roses have live green tissue that needs to heal quickly to prevent disease (common in damp Seattle climates). Bypass shears provide a clean slice that leaves the plant's vascular system intact.",
          "variant": "body"
        },
        {
          "id": "damage-col",
          "component": "Column",
          "children": [
            "damage-h",
            "damage-body"
          ]
        },
        {
          "id": "damage-h",
          "component": "Text",
          "text": "Why Anvil Shears Damage Live Tissue",
          "variant": "h4"
        },
        {
          "id": "damage-body",
          "component": "Text",
          "text": "Anvil shears use a crushing motion to complete the cut. On live green stems, this crushing action bruises the delicate cambium layer and mashes the stem fibers. This creates a ragged wound that is slow to heal and serves as an entry point for fungi and pests. Anvil shears should only be used for dead, brittle wood where the crushing doesn't matter.",
          "variant": "body"
        },
        {
          "id": "tips-card",
          "component": "Card",
          "child": "tips-col"
        },
        {
          "id": "tips-col",
          "component": "Column",
          "children": [
            "tips-header-row",
            "tips-list"
          ]
        },
        {
          "id": "tips-header-row",
          "component": "Row",
          "children": [
            "icon-tools",
            "tips-title"
          ],
          "align": "center"
        },
        {
          "id": "icon-tools",
          "component": "Image",
          "url": "/maintenance.png",
          "variant": "icon"
        },
        {
          "id": "tips-title",
          "component": "Text",
          "text": "Seattle Gardening Tips for Roses",
          "variant": "h4"
        },
        {
          "id": "tips-list",
          "component": "Text",
          "text": "- Prune in late February or early March when the forsythia blooms.\n- Always cut at a 45-degree angle, 1/4 inch above an outward-facing bud.\n- Clean your blades with isopropyl alcohol between plants to prevent the spread of Black Spot or Mildew.",
          "variant": "body"
        },
        {
          "id": "action-row",
          "component": "Row",
          "children": [
            "btn-shop"
          ],
          "justify": "center"
        },
        {
          "id": "btn-shop",
          "component": "Button",
          "child": "btn-text",
          "variant": "primary",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "/shop/bypass-pruners"
              }
            }
          }
        },
        {
          "id": "btn-text",
          "component": "Text",
          "text": "Shop Bypass Pruners"
        }
      ]
    }
  }
]

